const API = 'http://127.0.0.1:8409/api/v1';
const owner = 'hugo-berendi';
const repos = await this.helpers.httpRequest({method: 'GET', url: `${API}/users/${owner}/repos`, qs: {limit: 100}, json: true});
const current = {};

for (const repo of repos.filter((item) => !item.private && !item.archived)) {
  let releases = [];
  try {
    releases = await this.helpers.httpRequest({
      method: 'GET',
      url: `${API}/repos/${owner}/${repo.name}/releases`,
      qs: {limit: 20},
      json: true,
    });
  } catch (error) {
    // Forgejo returns 404 when a repository has no releases.
    if (Number(error?.statusCode ?? error?.response?.statusCode) !== 404) throw error;
  }
  for (const release of Array.isArray(releases) ? releases : []) {
    if (release.draft) continue;
    current[`${repo.name}:${release.id}`] = {
      repo: repo.name,
      name: release.name || release.tag_name,
      tag: release.tag_name,
      url: release.html_url,
      publishedAt: release.published_at,
      prerelease: Boolean(release.prerelease),
    };
  }
}

const state = $getWorkflowStaticData('global');
if (!state.releases) {
  state.releases = current;
  return [];
}
const added = Object.entries(current).filter(([id]) => !(id in state.releases)).map(([, release]) => release);
if (!added.length) return [];
const esc = (value) =>
  String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
const rows = added
  .map((release) => `<tr><td style="padding:10px 0;border-bottom:1px solid #393552;color:#e0def4;"><a href="${esc(release.url)}" style="color:#9ccfd8;font-weight:bold;">${esc(release.repo)} ${esc(release.tag)}</a><br><span style="color:#908caa;">${esc(release.name)}${release.prerelease ? ' · prerelease' : ''}</span></td></tr>`)
  .join('');
const html = `<html><body style="margin:0;padding:24px;background:#232136;"><table role="presentation" width="100%" style="max-width:600px;margin:auto;background:#2a273f;border:1px solid #393552;padding:24px;font-family:Verdana,sans-serif;"><tr><td style="color:#c4a7e7;font:700 20px 'Courier New',monospace;">FORGEJO RELEASES</td></tr>${rows}</table></body></html>`;
return [{json: {subject: `[Forgejo] ${added.length} new release${added.length === 1 ? '' : 's'}`, html, nextState: current}}];

const nextState = $('Check public releases').first().json.nextState;
const state = $getWorkflowStaticData('global');
state.releases = nextState;
return $input.all();
